39	    static void preOrder(Node root, ArrayList<String> ans, String curr) {
40	        if (root == null) return;
41	
42	        if (root.left == null && root.right == null) {
43	
44	            if (curr.equals("")) curr = "0";
45	
46	            ans.add(curr);
47	            return;
48	        }
49	
50	        preOrder(root.left, ans, curr + '0');
51	        preOrder(root.right, ans, curr + '1');
52	    }
