54	    static ArrayList<String> huffmanCodes(String s, int[] freq) {
55	
56	        int n = s.length();
57	
58	        PriorityQueue<Node> pq = new PriorityQueue<>(new Compare());
59	        for (int i = 0; i < n; i++) {
60	
61	            Node tmp = new Node(freq[i], i);
62	
63	            pq.add(tmp);
64	        }
65	
66	        if (n == 1) {
67	            ArrayList<String> res = new ArrayList<>();
68	            res.add("0");
69	            return res;
70	        }
71	
72	        while (pq.size() >= 2) {
73	
74	            Node l = pq.poll();
75	
76	            Node r = pq.poll();
77	
78	            Node newNode = new Node(l, r);
79	
80	            pq.add(newNode);
81	        }
82	
83	        Node root = pq.peek();
84	        ArrayList<String> ans = new ArrayList<>();
85	        preOrder(root, ans, "");
86	        return ans;
87	    }
