 1	import java.util.ArrayList;
 2	import java.util.Comparator;
 3	import java.util.PriorityQueue;
 4	
 5	public class HuffmanCoding {
 6	    private static final String SINGLE_SYMBOL_CODE = "0";
 7	    private static final Comparator<Node> NODE_ORDER =
 8	            Comparator.comparingInt((Node node) -> node.frequency)
 9	                    .thenComparingInt(node -> node.order);
10	
11	    private static final class Node {
12	        private final int frequency;
13	        private final int order;
14	        private final Node left;
15	        private final Node right;
16	
17	        private Node(int frequency, int order) {
18	            this(frequency, order, null, null);
19	        }
20	
21	        private Node(Node left, Node right) {
22	            this(left.frequency + right.frequency, Math.min(left.order, right.order), left, right);
23	        }
24	
25	        private Node(int frequency, int order, Node left, Node right) {
26	            this.frequency = frequency;
27	            this.order = order;
28	            this.left = left;
29	            this.right = right;
30	        }
31	
32	        private boolean isLeaf() {
33	            return left == null && right == null;
34	        }
35	    }
36	
37	    static ArrayList<String> huffmanCodes(String s, int[] freq) {
38	        PriorityQueue<Node> queue = buildLeafQueue(s, freq);
39	        Node root = buildTree(queue);
40	        ArrayList<String> codes = new ArrayList<>();
41	        collectCodes(root, new StringBuilder(), codes);
42	        return codes;
43	    }
44	
45	    private static PriorityQueue<Node> buildLeafQueue(String symbols, int[] frequencies) {
46	        PriorityQueue<Node> queue = new PriorityQueue<>(NODE_ORDER);
47	        for (int i = 0; i < symbols.length(); i++) {
48	            queue.add(new Node(frequencies[i], i));
49	        }
50	        return queue;
51	    }
52	
53	    private static Node buildTree(PriorityQueue<Node> queue) {
54	        while (queue.size() > 1) {
55	            Node left = queue.poll();
56	            Node right = queue.poll();
57	            queue.add(new Node(left, right));
58	        }
59	        return queue.peek();
60	    }
61	
62	    private static void collectCodes(Node node, StringBuilder path, ArrayList<String> codes) {
63	        if (node == null) {
64	            return;
65	        }
66	
67	        if (node.isLeaf()) {
68	            codes.add(path.length() == 0 ? SINGLE_SYMBOL_CODE : path.toString());
69	            return;
70	        }
71	
72	        path.append('0');
73	        collectCodes(node.left, path, codes);
74	        path.deleteCharAt(path.length() - 1);
75	
76	        path.append('1');
77	        collectCodes(node.right, path, codes);
78	        path.deleteCharAt(path.length() - 1);
79	    }
80	
81	    public static void main(String[] args) {
82	        String s = "abcdef";
83	        int[] freq = {5, 9, 12, 13, 16, 45};
84	        ArrayList<String> ans = huffmanCodes(s, freq);
85	        for (String code : ans) {
86	            System.out.print(code + " ");
87	        }
88	    }
89	}
